#!/usr/bin/env python3
"""Worked computer activities, with exact algorithms and embedded cloud models."""
import copy
import json
import math
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
COURSE=ROOT/'stereo-course/merzlyak-10-base'
OUT=COURSE/'lessons'
INDEX=json.loads((COURSE/'source-index.json').read_text())
ENTRIES={e['id']:e for e in INDEX['entries']}
COVERAGE={}

def theory(n):return copy.deepcopy(json.loads((OUT/f'theory-{n:02}.json').read_text())['visualization'])

def write(n,part,title,question,visual,explanations,pages=None):
    entry=ENTRIES[f'source-computer-{n}']
    source=copy.deepcopy(entry['source']);source.pop('paragraph',None)
    source['subpart']=part
    if pages:source['pdfPages']=pages;source['printedPages']=[p-1 for p in pages]
    views=list(visual['model']['views'])
    steps=[]
    for i,item in enumerate(explanations,1):
        if len(item)==2:heading,text=item;view='neutral'
        else:heading,text,view=item
        assert view in views,(n,part,view)
        steps.append({'id':f'step-{i}','title':heading,'prompt':heading+' — объясни действие и проверь результат.',
          'explanation':text,'justifications':[{'kind':'theorem','text':'Определения и доказанные свойства соответствующего параграфа; указанные в шаге координатные вычисления.'}],'view':view})
    number=len(COVERAGE.setdefault(n,[]))+1
    filename=f'computer-{n:02}-{number:02}.json'
    lesson={'schemaVersion':1,'revision':1,'id':f'merz-computer-{n:02}-{number:02}',
      'kind':'exercise','title':f'Компьютер · § {n}: {title}','status':'draft','source':source,
      'statement':{'text':question,'goal':'Выполнить построение или записать проверяемый алгоритм, объясняя геометрические основания каждого действия.'},
      'visualization':visual,'help':[{'id':'help-1','question':'Как начать работу?',
        'text':'Сначала назови входные объекты и требуемый результат. Используй встроенную модель: её можно вращать. Затем открывай шаги и записывай собственное построение или алгоритм. Числа на рисунке не измеряют по экрану.','children':[]}],
      'steps':steps,'answer':{'mode':'manual','prompt':'Запиши построение или алгоритм и результат его проверки на примере. Эта запись сохраняется; полноценная программа и геометрическое доказательство требуют обсуждения с преподавателем.'},
      'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
    (OUT/filename).write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n')
    COVERAGE[n].append({'part':part,'file':f'stereo-course/merzlyak-10-base/lessons/{filename}','pdfPages':source['pdfPages']})

def clone_exercise(n,part,filename):
    original=json.loads((OUT/filename).read_text())
    write(n,part,'Построение к № '+part,
      'Постройте изображение к упражнению '+part+' с помощью графического редактора. '+original['statement']['text'],
      copy.deepcopy(original['visualization']),
      [('Подготовка чертежа','Задай точки и исходные рёбра. Сохраняй заданные отношения; линии, скрытые гранями, показывай штрихами. Встроенная модель содержит готовый пример построения.')]+
      [(s['title'],s['explanation'],s['view']) for s in original['steps']]+
      [('Проверка изображения','Поверни модель и проверь принадлежность точек прямым и плоскостям по построению. Плоское пересечение двух линий на экране само по себе не означает пересечение пространственных прямых.')])

def revolution(cone=False):
    p={'O':[0,0,0],'H':[0,0,3]};edges=[];faces=[]
    for i in range(16):
        angle=2*math.pi*i/16;p[f'B{i}']=[2*math.cos(angle),2*math.sin(angle),0]
        if not cone:p[f'T{i}']=[2*math.cos(angle),2*math.sin(angle),3]
    for i in range(16):
        j=(i+1)%16;edges.append([f'B{i}',f'B{j}'])
        if cone:edges.append([f'B{i}','H']);faces.append([f'B{i}',f'B{j}','H'])
        else:
            edges.extend([[f'T{i}',f'T{j}'],[f'B{i}',f'T{i}']]);faces.append([f'B{i}',f'B{j}',f'T{j}',f'T{i}'])
    faces.append([f'B{i}' for i in range(16)])
    if not cone:faces.append([f'T{i}' for i in range(16)])
    edges.append(['O','H'])
    return {'type':'scene3d','caption':('Конус' if cone else 'Цилиндр')+' изображён сеткой: круги аппроксимированы правильными 16-угольниками. Сетка служит для показа формы; точные проекции описаны в решении.',
      'model':{'points':p,'edges':edges,'faces':faces,'labelNames':['O','H'],
      'views':{'neutral':{'label':'Вращай модель и наблюдай проекцию'},'axis':{'label':'Ось перпендикулярна основаниям','segments':[['O','H']]},
      'base':{'label':'Основание — круг; здесь его приближённая сетка','polygon':[f'B{i}' for i in range(16)]}}}}

def parallelepiped(oblique=False):
    v=theory(17)
    if not oblique:return v
    for p in v['model']['points'].values():p[0]+=0.55*p[2];p[1]+=0.25*p[2]
    v['caption']='Наклонный параллелепипед: все три семейства рёбер сохраняют параллельность; прямые углы между измерениями не заявлены.'
    a1=v['model']['points']['A1'];v['model']['points']['H']=[a1[0],a1[1],0]
    v['model']['edges'].append(['A1','H'])
    v['model']['labelNames']=['A','B','C','D','A1','H']
    v['model']['views']={'neutral':{'label':'Наклонный параллелепипед и его высота A₁H'},'base':{'label':'Основание-параллелограмм','polygon':['A','B','C','D']},'height':{'label':'Высота A₁H перпендикулярна основанию','segments':[['A1','H']]}}
    return v

def main():
    write(1,'плоскости','Плоскости и видимость','Освойте изображение плоскостей и невидимых частей фигур; обратите внимание на рисунки 1.7 и 1.8.',theory(1),[
      ('Фрагмент плоскости','Плоскость бесконечна; для рисунка выбирают ограниченный многоугольный фрагмент. В модели ABC и ABD — фрагменты двух плоскостей, а не сами бесконечные плоскости.','plane'),
      ('Линия пересечения','Сначала построй две общие точки A и B и проведи AB. Обе плоскости содержат всю AB; продолжение за пределы закраски не меняет этого.','other'),
      ('Невидимая часть','Выбери направление взгляда. Часть линии за непрозрачной гранью рисуют штрихами, видимую — сплошной. После поворота видимость может измениться, но принадлежность точек не меняется.')])
